# --- Sem 5: Billing (Stripe checkout + portal + plan state) ---

def _serialize_billing_subscription(sub: sqlite3.Row) -> BillingSubscriptionPublic:
    if not sub:
        free = SELF_SERVE_PLANS["free"]
        return BillingSubscriptionPublic(
            plan="free", status="active",
            messages_quota=int(free["messages_quota"]),
            messages_used=0,
            messages_remaining=int(free["messages_quota"]),
            cancel_at_period_end=False,
            current_period_start="", current_period_end="",
            stripe_customer_id="",
        )
    quota = int(sub["messages_quota"] or 0)
    used = int(sub["messages_used_period"] or 0)
    return BillingSubscriptionPublic(
        plan=sub["plan"] or "free",
        status=sub["status"] or "active",
        messages_quota=quota,
        messages_used=used,
        messages_remaining=max(0, quota - used),
        cancel_at_period_end=bool(sub["cancel_at_period_end"]),
        current_period_start=sub["current_period_start"] or "",
        current_period_end=sub["current_period_end"] or "",
        stripe_customer_id=sub["stripe_customer_id"] or "",
    )


def _build_plan_tiers(current_plan_slug: str) -> List[BillingPlanTier]:
    out: List[BillingPlanTier] = []
    for slug in ["free", "starter", "pro", "business"]:
        plan = SELF_SERVE_PLANS[slug]
        limits = _plan_limits(slug)
        out.append(BillingPlanTier(
            slug=plan["slug"],
            label=plan["label"],
            price_monthly_eur=int(plan["price_monthly_eur"]),
            price_annual_eur=int(plan["price_annual_eur"]),
            messages_quota=int(plan["messages_quota"]),
            bookings_quota=limits.get("monthly_bookings"),
            features=list(plan["features"]),
            has_monthly_price_id=bool(plan["stripe_price_monthly"]),
            has_annual_price_id=bool(plan["stripe_price_annual"]),
            is_current=(slug == current_plan_slug),
        ))
    return out


def _stripe_connect_headers() -> Dict[str, str]:
    if not _stripe_connect_configured():
        raise HTTPException(status_code=503, detail="Stripe no configurado en el servidor.")
    return {
        "Authorization": f"Bearer {STRIPE_SECRET_KEY}",
        "Stripe-Version": STRIPE_CONNECT_API_VERSION,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }


def _stripe_connect_configured() -> bool:
    return bool(STRIPE_SECRET_KEY)


def _stripe_connect_request(method: str, path: str, *, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    try:
        with httpx.Client(timeout=25.0) as client:
            response = client.request(
                method,
                f"{STRIPE_CONNECT_BASE_URL}{path}",
                headers=_stripe_connect_headers(),
                json=payload,
            )
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail="No se pudo conectar con Stripe Connect.") from exc
    try:
        body = response.json()
    except ValueError:
        body = {}
    if response.is_error:
        message = (
            body.get("error", {}).get("message", "")
            if isinstance(body.get("error"), dict)
            else ""
        )
        logger.error("Stripe Connect %s %s fallo (%s): %s", method, path, response.status_code, message)
        raise HTTPException(
            status_code=502,
            detail=message or "Stripe no pudo completar la operacion de conexion.",
        )
    return body


def _stripe_connected_account_row(cliente_id: str) -> Optional[sqlite3.Row]:
    with _get_db_connection() as connection:
        return connection.execute(
            "SELECT * FROM stripe_connected_accounts WHERE cliente_id = ?",
            (cliente_id,),
        ).fetchone()


def _save_stripe_connected_account(
    cliente_id: str,
    owner_user_id: str,
    stripe_account_id: str,
    *,
    status_value: str = "pending",
    requirements_due: int = 0,
    last_error: str = "",
) -> None:
    now_iso = _utc_now_iso()
    with _get_db_connection() as connection:
        connection.execute(
            """
            INSERT INTO stripe_connected_accounts
                (cliente_id, owner_user_id, stripe_account_id, status,
                 requirements_due, last_error, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(cliente_id) DO UPDATE SET
                owner_user_id = excluded.owner_user_id,
                stripe_account_id = excluded.stripe_account_id,
                status = excluded.status,
                requirements_due = excluded.requirements_due,
                last_error = excluded.last_error,
                updated_at = excluded.updated_at
            """,
            (
                cliente_id,
                owner_user_id,
                stripe_account_id,
                status_value,
                requirements_due,
                last_error,
                now_iso,
                now_iso,
            ),
        )
        connection.commit()


def _stripe_connect_requirement_count(account: Dict[str, Any]) -> int:
    requirements = account.get("requirements")
    if not isinstance(requirements, dict):
        return 0
    entries = requirements.get("entries")
    return len(entries) if isinstance(entries, list) else 0


def _stripe_connect_account_status(account: Dict[str, Any]) -> Tuple[str, int]:
    due = _stripe_connect_requirement_count(account)
    merchant = account.get("configuration", {}).get("merchant", {})
    card_payments = merchant.get("capabilities", {}).get("card_payments", {})
    capability_status = str(card_payments.get("status", "")).lower()
    if capability_status == "active" and due == 0:
        return "active", 0
    return ("requirements_due" if due else "pending"), due


def _stripe_connect_display_name(cliente_id: str) -> str:
    config = CONFIG_CLIENTES.get(cliente_id, {})
    configured_name = str(config.get("nombre", "")).strip()
    if configured_name:
        return configured_name
    with _get_db_connection() as connection:
        row = connection.execute(
            "SELECT nombre FROM clientes WHERE cliente_id = ?",
            (cliente_id,),
        ).fetchone()
    return str(row["nombre"] or cliente_id).strip() if row else cliente_id


def _create_stripe_connected_account(user: sqlite3.Row) -> str:
    cliente_id = str(user["cliente_id"] or "")
    payload = {
        "contact_email": user["email"],
        "display_name": _stripe_connect_display_name(cliente_id),
        "dashboard": "full",
        "identity": {
            "country": STRIPE_CONNECT_COUNTRY,
        },
        "configuration": {
            "merchant": {
                "capabilities": {
                    "card_payments": {"requested": True},
                },
            },
        },
        "defaults": {
            "currency": "eur",
            "responsibilities": {
                "fees_collector": "stripe",
                "losses_collector": "stripe",
            },
            "locales": ["es-ES"],
        },
        "include": ["configuration.merchant", "requirements"],
    }
    account = _stripe_connect_request("POST", "/accounts", payload=payload)
    account_id = str(account.get("id", ""))
    if not account_id:
        raise HTTPException(status_code=502, detail="Stripe no devolvio una cuenta conectada valida.")
    status_value, due = _stripe_connect_account_status(account)
    _save_stripe_connected_account(
        cliente_id,
        user["id"],
        account_id,
        status_value=status_value,
        requirements_due=due,
    )
    return account_id


def _stripe_connect_account_id(user: sqlite3.Row) -> str:
    cliente_id = str(user["cliente_id"] or "")
    if not cliente_id:
        raise HTTPException(status_code=400, detail="Tu usuario no tiene un negocio asociado.")
    row = _stripe_connected_account_row(cliente_id)
    return str(row["stripe_account_id"]) if row else _create_stripe_connected_account(user)


def _stripe_connect_onboarding_url(user: sqlite3.Row, request: Request) -> str:
    account_id = _stripe_connect_account_id(user)
    base_url = _public_base_url(request)
    account_link = _stripe_connect_request(
        "POST",
        "/account_links",
        payload={
            "account": account_id,
            "use_case": {
                "type": "account_onboarding",
                "account_onboarding": {
                    "collection_options": {"fields": "eventually_due"},
                    "configurations": ["merchant"],
                    "return_url": f"{base_url}/auth/app/stripe-connect/return",
                    "refresh_url": f"{base_url}/auth/app/stripe-connect/refresh",
                },
            },
        },
    )
    onboarding_url = str(account_link.get("url", ""))
    if not onboarding_url:
        raise HTTPException(status_code=502, detail="Stripe no devolvio un enlace de conexion valido.")
    return onboarding_url


@app.get("/auth/app/stripe-connect", response_model=StripeConnectStateResponse)
async def app_stripe_connect_state(
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> StripeConnectStateResponse:
    cliente_id = str(user["cliente_id"] or "")
    if not cliente_id:
        raise HTTPException(status_code=400, detail="Tu usuario no tiene un negocio asociado.")
    row = _stripe_connected_account_row(cliente_id)
    if not row:
        return StripeConnectStateResponse(configured=_stripe_connect_configured())
    status_value = str(row["status"] or "pending")
    requirements_due = int(row["requirements_due"] or 0)
    last_error = ""
    if _stripe_connect_configured():
        try:
            account = _stripe_connect_request(
                "GET",
                f"/accounts/{row['stripe_account_id']}?include[0]=configuration.merchant&include[1]=requirements",
            )
            status_value, requirements_due = _stripe_connect_account_status(account)
            _save_stripe_connected_account(
                cliente_id,
                user["id"],
                row["stripe_account_id"],
                status_value=status_value,
                requirements_due=requirements_due,
            )
        except HTTPException as exc:
            last_error = str(exc.detail)
            _save_stripe_connected_account(
                cliente_id,
                user["id"],
                row["stripe_account_id"],
                status_value=status_value,
                requirements_due=requirements_due,
                last_error=last_error,
            )
    return StripeConnectStateResponse(
        configured=_stripe_connect_configured(),
        connected=True,
        stripe_account_id=row["stripe_account_id"],
        status=status_value,
        requirements_due=requirements_due,
        last_error=last_error,
    )


@app.post("/auth/app/stripe-connect/start", response_model=StripeConnectStartResponse)
async def app_stripe_connect_start(
    request: Request,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> StripeConnectStartResponse:
    if _session_is_impersonated(user):
        raise HTTPException(status_code=403, detail="Accion bloqueada en sesion de admin (impersonacion).")
    return StripeConnectStartResponse(ok=True, onboarding_url=_stripe_connect_onboarding_url(user, request))


@app.get("/auth/app/stripe-connect/refresh")
async def app_stripe_connect_refresh(
    request: Request,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> RedirectResponse:
    if _session_is_impersonated(user):
        raise HTTPException(status_code=403, detail="Accion bloqueada en sesion de admin (impersonacion).")
    return RedirectResponse(_stripe_connect_onboarding_url(user, request), status_code=303)


@app.get("/auth/app/stripe-connect/return")
async def app_stripe_connect_return(
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> RedirectResponse:
    return RedirectResponse("/app?stripe_connect=returned", status_code=303)


def resolve_payment_requirement(
    cliente_id: str,
    service: Optional[sqlite3.Row],
    booking: Optional[sqlite3.Row] = None,
) -> Dict[str, Any]:
    mode = str(service["payment_mode"] or "payment_disabled") if service else "payment_disabled"
    payment_type = str(service["payment_type"] or "full") if service else "full"
    currency = str(service["currency"] or "eur").lower() if service else "eur"
    full_amount = int(
        (booking["service_price_cents"] if booking else service["price_cents"]) or 0
    ) if service else 0
    deposit = int(service["deposit_amount_cents"] or 0) if service else 0
    amount = deposit if payment_type == "deposit" and deposit > 0 else full_amount
    account = _stripe_connected_account_row(cliente_id)
    stripe_active = bool(account and account["status"] == "active" and _stripe_configured())
    available = stripe_active and amount > 0 and mode != "payment_disabled"
    return {
        "mode": mode,
        "payment_type": payment_type,
        "currency": currency,
        "amount_cents": amount if available else 0,
        "stripe_account_id": account["stripe_account_id"] if available else "",
        "payment_required": bool(available and mode == "payment_required"),
        "payment_optional": bool(available and mode == "payment_optional"),
        "payment_status": "pending" if available and mode == "payment_required" else "optional" if available else "not_required",
    }


def _booking_payment_row(booking_id: str) -> Optional[sqlite3.Row]:
    with _get_db_connection() as connection:
        return connection.execute(
            "SELECT * FROM booking_payments WHERE booking_id = ?",
            (booking_id,),
        ).fetchone()


def create_booking_payment_checkout(cliente_id: str, booking_id: str, request: Optional[Request] = None) -> str:
    booking = _load_booking_or_404(booking_id)
    if booking["cliente_id"] != cliente_id:
        raise HTTPException(status_code=403, detail="No tienes acceso a esta reserva.")
    service = _get_service_row(cliente_id, booking["service_id"]) or _find_service_by_name(
        cliente_id, booking["servicio"]
    )
    decision = resolve_payment_requirement(cliente_id, service, booking)
    if not decision["payment_required"] and not decision["payment_optional"]:
        raise HTTPException(status_code=409, detail="Esta reserva no tiene un pago Stripe disponible.")
    existing = _booking_payment_row(booking_id)
    if existing and existing["status"] == "paid":
        return existing["checkout_url"] or ""
    if existing and existing["checkout_url"]:
        return existing["checkout_url"]
    _stripe_init()
    base_url = _preferred_public_base_url(request).rstrip("/")
    if not base_url:
        raise HTTPException(status_code=503, detail="APP_BASE_URL no configurada para generar enlaces de pago.")
    try:
        session = stripe.checkout.Session.create(
            stripe_account=decision["stripe_account_id"],
            mode="payment",
            line_items=[{
                "price_data": {
                    "currency": decision["currency"],
                    "product_data": {"name": booking["servicio"] or "Reserva"},
                    "unit_amount": decision["amount_cents"],
                },
                "quantity": 1,
            }],
            customer_email=booking["email"] or None,
            success_url=f"{base_url}/reservas/{booking['manage_token']}?payment=success",
            cancel_url=f"{base_url}/reservas/{booking['manage_token']}?payment=cancel",
            expires_at=int(time.time()) + BOOKING_PAYMENT_EXPIRY_MINUTES * 60,
            metadata={
                "source": "booking_payment",
                "cliente_id": cliente_id,
                "booking_id": booking_id,
            },
            payment_intent_data={
                "metadata": {
                    "source": "booking_payment",
                    "cliente_id": cliente_id,
                    "booking_id": booking_id,
                },
            },
        )
    except Exception as exc:  # noqa: BLE001
        logger.error("Stripe booking checkout fallo cliente=%s booking=%s: %s", cliente_id, booking_id, exc)
        raise HTTPException(status_code=502, detail="No se pudo crear el enlace de pago.") from exc
    now = _utc_now_iso()
    with _get_db_connection() as connection:
        connection.execute(
            """
            INSERT INTO booking_payments
                (id, cliente_id, booking_id, stripe_account_id, checkout_session_id,
                 amount_cents, currency, status, checkout_url, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?)
            ON CONFLICT(booking_id) DO UPDATE SET
                checkout_session_id=excluded.checkout_session_id,
                checkout_url=excluded.checkout_url,
                updated_at=excluded.updated_at
            """,
            (
                f"pay_{secrets.token_urlsafe(10)}", cliente_id, booking_id,
                decision["stripe_account_id"], session.id or "",
                decision["amount_cents"], decision["currency"], session.url or "", now, now,
            ),
        )
        connection.execute(
            """
            UPDATE bookings
            SET payment_status = CASE WHEN status = 'pending_payment' THEN 'pending' ELSE 'optional' END
            WHERE id = ?
            """,
            (booking_id,),
        )
        connection.commit()
    return session.url or ""


def _booking_payment_after_store(booking_id: str, request: Optional[Request] = None) -> str:
    booking = _get_booking_row_by_id(booking_id)
    if not booking or booking["payment_status"] not in {"pending", "optional"}:
        return ""
    try:
        return create_booking_payment_checkout(booking["cliente_id"], booking_id, request)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Pago opcional no disponible booking=%s: %s", booking_id, exc)
        if booking["status"] == "pending_payment":
            _update_booking_record(
                booking_id,
                status="confirmed",
                confirmed_at=_utc_now_iso(),
                payment_status="not_required",
            )
        return ""


def process_booking_payment_webhook(data_object: Dict[str, Any]) -> bool:
    metadata = data_object.get("metadata") or {}
    if metadata.get("source") != "booking_payment":
        return False
    booking_id = str(metadata.get("booking_id") or "")
    cliente_id = str(metadata.get("cliente_id") or "")
    if not booking_id or not cliente_id:
        return True
    now = _utc_now_iso()
    session_id = str(data_object.get("id") or "")
    payment_intent_id = str(data_object.get("payment_intent") or "")
    with _get_db_connection() as connection:
        row = connection.execute(
            "SELECT status FROM booking_payments WHERE booking_id = ?",
            (booking_id,),
        ).fetchone()
        if row and row["status"] == "paid":
            return True
        connection.execute(
            """
            UPDATE booking_payments
            SET status='paid', checkout_session_id=?, payment_intent_id=?,
                paid_at=?, updated_at=?
            WHERE booking_id=? AND cliente_id=?
            """,
            (session_id, payment_intent_id, now, now, booking_id, cliente_id),
        )
        booking = connection.execute(
            "SELECT status FROM bookings WHERE id = ? AND cliente_id = ?",
            (booking_id, cliente_id),
        ).fetchone()
        connection.execute(
            """
            UPDATE bookings
            SET payment_status='paid',
                status=CASE WHEN status IN ('pending_payment', 'confirmed') THEN 'confirmed' ELSE status END,
                confirmed_at=CASE
                    WHEN status IN ('pending_payment', 'confirmed') AND confirmed_at='' THEN ?
                    ELSE confirmed_at
                END
            WHERE id=? AND cliente_id=?
            """,
            (now, booking_id, cliente_id),
        )
        connection.commit()
    _record_booking_audit(booking_id, cliente_id, "booking_payment_paid", {"checkout_session_id": session_id})
    refreshed = _get_booking_row_by_id(booking_id)
    if refreshed and refreshed["status"] == "confirmed" and booking and booking["status"] == "pending_payment":
        try:
            _send_booking_email(refreshed, "confirmed")
        except Exception as exc:  # noqa: BLE001
            logger.warning("No se pudo enviar confirmacion tras pago booking=%s: %s", booking_id, exc)
    return True


def process_booking_payment_expired_webhook(data_object: Dict[str, Any]) -> bool:
    metadata = data_object.get("metadata") or {}
    if metadata.get("source") != "booking_payment":
        return False
    booking_id = str(metadata.get("booking_id") or "")
    cliente_id = str(metadata.get("cliente_id") or "")
    if not booking_id or not cliente_id:
        return True
    now = _utc_now_iso()
    with _get_db_connection() as connection:
        booking = connection.execute(
            "SELECT status, payment_status FROM bookings WHERE id = ? AND cliente_id = ?",
            (booking_id, cliente_id),
        ).fetchone()
        if not booking or booking["payment_status"] == "paid":
            return True
        connection.execute(
            "UPDATE booking_payments SET status='expired', updated_at=? WHERE booking_id=? AND cliente_id=?",
            (now, booking_id, cliente_id),
        )
        if booking["status"] == "pending_payment":
            connection.execute(
                "UPDATE bookings SET status='cancelled', payment_status='expired', cancelled_at=? WHERE id=?",
                (now, booking_id),
            )
        else:
            connection.execute(
                "UPDATE bookings SET payment_status='expired' WHERE id=?",
                (booking_id,),
            )
        connection.commit()
    _record_booking_audit(booking_id, cliente_id, "booking_payment_expired", {})
    return True


@app.get("/auth/bookings/{booking_id}/payment", response_model=BookingPaymentStateResponse)
async def auth_booking_payment_state(
    booking_id: str,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> BookingPaymentStateResponse:
    booking = _load_booking_or_404(booking_id)
    if user["role"] != "admin" and booking["cliente_id"] != user["cliente_id"]:
        raise HTTPException(status_code=403, detail="No tienes acceso a esta reserva.")
    service = _get_service_row(booking["cliente_id"], booking["service_id"]) or _find_service_by_name(
        booking["cliente_id"], booking["servicio"]
    )
    decision = resolve_payment_requirement(booking["cliente_id"], service, booking)
    payment = _booking_payment_row(booking_id)
    return BookingPaymentStateResponse(
        booking_id=booking_id,
        payment_required=decision["payment_required"],
        payment_optional=decision["payment_optional"],
        payment_status=payment["status"] if payment else booking["payment_status"],
        amount_cents=int(payment["amount_cents"] if payment else decision["amount_cents"]),
        currency=payment["currency"] if payment else decision["currency"],
        checkout_url=payment["checkout_url"] if payment else "",
    )


@app.post("/auth/bookings/{booking_id}/payment/checkout", response_model=BookingPaymentStateResponse)
async def auth_booking_payment_checkout(
    booking_id: str,
    request: Request,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> BookingPaymentStateResponse:
    booking = _load_booking_or_404(booking_id)
    if user["role"] != "admin" and booking["cliente_id"] != user["cliente_id"]:
        raise HTTPException(status_code=403, detail="No tienes acceso a esta reserva.")
    checkout_url = create_booking_payment_checkout(booking["cliente_id"], booking_id, request)
    payment = _booking_payment_row(booking_id)
    service = _get_service_row(booking["cliente_id"], booking["service_id"]) or _find_service_by_name(
        booking["cliente_id"], booking["servicio"]
    )
    decision = resolve_payment_requirement(booking["cliente_id"], service, booking)
    return BookingPaymentStateResponse(
        booking_id=booking_id,
        payment_required=decision["payment_required"],
        payment_optional=decision["payment_optional"],
        payment_status=payment["status"] if payment else booking["payment_status"],
        amount_cents=int(payment["amount_cents"] if payment else 0),
        currency=payment["currency"] if payment else "eur",
        checkout_url=checkout_url,
    )


@app.get("/auth/app/billing", response_model=BillingStateResponse)
async def app_billing_state(
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> BillingStateResponse:
    sub = db_get_subscription_for_user(user["id"]) or db_ensure_free_subscription(user["id"])
    sub = _maybe_reset_subscription_period(sub)
    current_plan = (sub["plan"] or "free").lower()
    return BillingStateResponse(
        subscription=_serialize_billing_subscription(sub),
        plans=_build_plan_tiers(current_plan),
        portal_available=bool(sub["stripe_customer_id"]) and _stripe_configured(),
    )


@app.post("/auth/app/billing/checkout", response_model=BillingCheckoutResponse)
async def app_billing_checkout(
    data: BillingCheckoutPayload,
    request: Request,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> BillingCheckoutResponse:
    if _session_is_impersonated(user):
        raise HTTPException(status_code=403, detail="Acción bloqueada en sesión de admin (impersonación).")
    if not _stripe_configured():
        raise HTTPException(status_code=503, detail="Stripe no configurado en el servidor.")
    plan = _self_serve_plan(data.plan)
    if plan["slug"] == "free":
        raise HTTPException(status_code=400, detail="El plan Free no requiere checkout.")
    price_id = plan["stripe_price_annual"] if data.billing_period == "annual" else plan["stripe_price_monthly"]
    if not price_id:
        raise HTTPException(
            status_code=503,
            detail=f"STRIPE_PRICE_{plan['slug'].upper()}{'_ANNUAL' if data.billing_period == 'annual' else ''} no configurado.",
        )
    stripe.api_key = STRIPE_SECRET_KEY
    api_base = _public_base_url(request)
    sub = db_get_subscription_for_user(user["id"]) or db_ensure_free_subscription(user["id"])
    customer_kwargs: Dict[str, Any] = {}
    if sub["stripe_customer_id"]:
        customer_kwargs["customer"] = sub["stripe_customer_id"]
    else:
        customer_kwargs["customer_email"] = user["email"]
    session_kwargs: Dict[str, Any] = {
        "mode": "subscription",
        # Si el total recurrente queda en 0 (p.ej. cupon 100% forever), Stripe
        # no pide tarjeta. Para planes de pago normales sigue exigiendola.
        "payment_method_collection": "if_required",
        "line_items": [{"price": price_id, "quantity": 1}],
        "success_url": f"{api_base}/app?billing=success&plan={plan['slug']}",
        "cancel_url": f"{api_base}/app?billing=cancel",
        "client_reference_id": f"self_serve:{user['id']}",
        "metadata": {
            "source": "self_serve",
            "user_id": user["id"],
            "cliente_id": user["cliente_id"] or "",
            "plan": plan["slug"],
            "billing_period": data.billing_period,
        },
        **customer_kwargs,
    }
    coupon_id = (data.coupon or "").strip()
    if coupon_id:
        # Direct coupon injection (server-side). Stripe rejects invalid coupons with 400.
        # `allow_promotion_codes` and `discounts` are mutually exclusive in Checkout.
        session_kwargs["discounts"] = [{"coupon": coupon_id}]
    else:
        session_kwargs["allow_promotion_codes"] = True
    try:
        session = stripe.checkout.Session.create(**session_kwargs)
    except Exception as exc:  # noqa: BLE001
        logger.error("Stripe checkout self-serve fallo user=%s plan=%s: %s", user["id"], plan["slug"], exc)
        raise HTTPException(status_code=502, detail="No se pudo iniciar el checkout.") from exc
    _try_record_analytics_event(
        {
            "event": "checkout_started",
            "event_source": "vantelia_app",
            "widget_client_id": user["cliente_id"] or "",
            "cliente_id": user["cliente_id"] or "",
            "user_id": user["id"],
            "plan": plan["slug"],
            "billing_period": data.billing_period,
            "checkout_session_id": session.id or "",
            "source": "self_serve",
        },
        request,
    )
    _try_record_analytics_event(
        {
            "event": "upgrade_started",
            "event_source": "vantelia_app",
            "widget_client_id": user["cliente_id"] or "",
            "cliente_id": user["cliente_id"] or "",
            "user_id": user["id"],
            "plan": plan["slug"],
            "billing_period": data.billing_period,
            "checkout_session_id": session.id or "",
            "source": "self_serve",
        },
        request,
    )
    return BillingCheckoutResponse(ok=True, checkout_url=session.url or "")


@app.post("/auth/app/billing/portal", response_model=BillingPortalResponse)
async def app_billing_portal(
    request: Request,
    user: sqlite3.Row = Depends(_require_authenticated_portal_user),
) -> BillingPortalResponse:
    if _session_is_impersonated(user):
        raise HTTPException(status_code=403, detail="Acción bloqueada en sesión de admin (impersonación).")
    if not _stripe_configured():
        raise HTTPException(status_code=503, detail="Stripe no configurado.")
    sub = db_get_subscription_for_user(user["id"])
    if not sub or not sub["stripe_customer_id"]:
        raise HTTPException(status_code=400, detail="No tienes una suscripcion de pago activa.")
    stripe.api_key = STRIPE_SECRET_KEY
    api_base = _public_base_url(request)
    try:
        portal = stripe.billing_portal.Session.create(
            customer=sub["stripe_customer_id"],
            return_url=f"{api_base}/app",
        )
    except Exception as exc:  # noqa: BLE001
        logger.error("Stripe portal fallo user=%s: %s", user["id"], exc)
        raise HTTPException(status_code=502, detail="No se pudo abrir el portal.") from exc
    return BillingPortalResponse(ok=True, portal_url=portal.url or "")


